package com.bank.duplicates;

import java.util.*;
import java.util.logging.Logger;

// Detects duplicate transaction references for National Bank of India fraud team.
public class DuplicateFinder {
    private static final Logger log = Logger.getLogger(DuplicateFinder.class.getName());

    // General case: frequency map. O(n) time, O(n) space. Any values.
    public List<String> findDuplicatesByMap(List<String> refs) {
        Map<String, Integer> freq = new HashMap<>();
        List<String> dups = new ArrayList<>();
        for (String ref : refs) {
            if (freq.merge(ref, 1, Integer::sum) == 2) {
                dups.add(ref);                  // report once, when it hits 2
            }
        }
        log.info(() -> "Map duplicates = " + dups);
        return dups;
    }

    // Optimized: values in 1..n, index-marking. O(n) time, O(1) extra space.
    // Restores the array before returning so the caller sees original data.
    public List<Integer> findDuplicatesByMarking(int[] ids) {
        List<Integer> dups = new ArrayList<>();
        for (int value : ids) {
            int idx = Math.abs(value) - 1;      // value is 1-based, index 0-based
            if (ids[idx] < 0) {
                dups.add(idx + 1);              // slot already flipped → duplicate
            } else {
                ids[idx] = -ids[idx];           // mark as seen
            }
        }
        for (int i = 0; i < ids.length; i++) {
            ids[i] = Math.abs(ids[i]);          // restore original values
        }
        log.info(() -> "Marking duplicates = " + dups);
        return dups;
    }
}
