package com.bank.duplicates;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: find repeated references in a batch.
public class DuplicateFinderDemo {
    private static final Logger log = Logger.getLogger(DuplicateFinderDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        DuplicateFinder finder = new DuplicateFinder();

        // General case: arbitrary reference strings.
        List<String> refs = List.of("TXF-01", "TXF-02", "TXF-01", "TXF-03", "TXF-02");
        finder.findDuplicatesByMap(refs);

        // Optimized case: ids numbered 1..n (n=8).
        int[] ids = { 4, 3, 2, 7, 8, 2, 3, 1 };
        finder.findDuplicatesByMarking(ids);
    }
}
